Free your mind from the illusion that tests are about code coverage. They are about truth. About knowing, without doubt, that when a user walks through your checkout, the path is clear.

```typescript
// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: The Matrix of mocks
const mockCart = {
  items: [{ id: '1', name: 'Red Pill', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPayment,
}));

const fillShippingForm = async (user: ReturnType<typeof userEvent.setup>) => {
  await user.type(screen.getByLabelText(/street address/i), '123 Nebuchadnezzar Lane');
  await user.type(screen.getByLabelText(/city/i), 'Zion');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '90210');
};

const fillPaymentForm = async (user: ReturnType<typeof userEvent.setup>) => {
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Neo Anderson');
};

describe('Checkout - The Path', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Red Pill', price: 99.99 }];
  });

  describe('Happy Path - Complete Awakening', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-001' });

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await fillShippingForm(user);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/red pill/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-001')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-001');
    });
  });

  describe('Form Validation - Knowing the Truth', () => {
    it('shows error when street address is empty', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Edge Cases - Seeing Beyond', () => {
    it('shows empty cart message and offers escape', async () => {
      mockCart.items = [];
      const onCancel = vi.fn();

      render(<Checkout onCancel={onCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure with grace', async () => {
      const user = userEvent.setup();
      mockPayment.processPayment.mockRejectedValue(new Error('Card declined'));

      render(<Checkout />);
      await fillShippingForm(user);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      await fillPaymentForm(user);
      await user.click(screen.getByRole('button', { name: /review order/i }));
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });

  describe('Accessibility - Freedom for All', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('marks invalid fields with aria-invalid', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });
});
